local function deepCopy(source)
    if type(source) ~= "table" then return source end
    local copy = {}
    for key, value in pairs(source) do copy[key] = deepCopy(value) end
    return copy
end
local function installArabic()
    if not EID or not EID.descriptions or not EID.descriptions.en_us then
        Isaac.DebugString("Arabic EID: ERROR - External Item Descriptions was not loaded.")
        return
    end
    -- Arabic has already been shaped and put in visual order for EID's LTR
    -- renderer. Wrap the word sequence in logical order, then restore visual
    -- order within each line; keep a leading stat/icon prefix on the first line.
    if EID.fitTextToWidth and not EID.ArabicPreviewWrappedLines then
        local fitTextToWidth = EID.fitTextToWidth
        local function reverseWords(value)
            local words = {}
            for word in string.gmatch(value, "%S+") do table.insert(words, word) end
            for i = 1, math.floor(#words / 2) do
                local j = #words - i + 1
                words[i], words[j] = words[j], words[i]
            end
            return table.concat(words, " ")
        end
        local function splitLeadingPrefix(value)
            local prefix = ""
            local arrow = string.sub(value, 1, 3)
            if arrow == "↑" or arrow == "↓" then
                prefix = arrow
                value = string.sub(value, 4)
            end
            while true do
                local spaces = string.match(value, "^%s*") or ""
                local startAt = #spaces + 1
                if string.sub(value, startAt, startAt + 1) ~= "{{" then
                    prefix = prefix .. spaces
                    value = string.sub(value, #spaces + 1)
                    break
                end
                local closeAt = string.find(value, "}}", startAt + 2, true)
                if not closeAt then break end
                prefix = prefix .. spaces .. string.sub(value, startAt, closeAt + 1)
                value = string.sub(value, closeAt + 2)
            end
            return prefix, value
        end
        EID.fitTextToWidth = function(self, text, textboxWidth, breakUtf8Chars, ...)
            local isArabic = type(text) == "string" and string.find(text, "[\216-\219\239]") ~= nil
            local hasNoLineBreak = isArabic and (string.find(text, "{{NoLB}}") or string.find(text, "{{NoLineBreak}}"))
            local hasColorMarkup = isArabic and (string.find(text, "{{Color") or string.find(text, "{{CR}}"))
            if not isArabic or hasNoLineBreak or hasColorMarkup or type(textboxWidth) ~= "number" then
                return fitTextToWidth(self, text, textboxWidth, breakUtf8Chars, ...)
            end

            local prefix, body = splitLeadingPrefix(text)
            local measureWidth = textboxWidth
            if prefix ~= "" then
                local prefixText = self:replaceAllMarkupWithSpaces(prefix)
                measureWidth = math.max(20, textboxWidth - self:getStrWidth(prefixText))
            end
            local lines = fitTextToWidth(self, reverseWords(body), measureWidth, breakUtf8Chars, ...)
            if type(lines) == "table" then
                for i, line in ipairs(lines) do
                    lines[i] = reverseWords(line)
                end
                if prefix ~= "" and #lines > 0 then lines[1] = prefix .. lines[1] end
            end
            return lines
        end
        EID.ArabicPreviewWrappedLines = true
    end
    -- Font:Load resolves custom fonts relative to the game's resources root.
    local fontPath = "mods/Arabic EID/resources/font/arabic.fnt"
    local fontOK = EID:loadFont(fontPath)
    if not fontOK then
        fontPath = modPath .. "resources/font/arabic.fnt"
        fontOK = EID:loadFont(fontPath)
    end
    if not fontOK then
        Isaac.DebugString("Arabic EID: ERROR - Arabic BMFont could not be loaded from either supported path; keeping EID text unchanged.")
        return
    end
    -- The font atlas is rasterized at 2x density. This proxy halves only text
    -- drawing and measuring, preserving EID's configured size, wrapping,
    -- cached lines, inline icon positions, and line spacing.
    if not EID.ArabicPreviewDensityFont then
        local sourceFont = EID.font
        local scaledFont = {}
        function scaledFont:Load(...) return sourceFont:Load(...) end
        function scaledFont:SetMissingCharacter(...) return sourceFont:SetMissingCharacter(...) end
        function scaledFont:IsLoaded(...) return sourceFont:IsLoaded(...) end
        function scaledFont:GetStringWidthUTF8(text)
            return sourceFont:GetStringWidthUTF8(text) * 0.5
        end
        function scaledFont:DrawStringScaledUTF8(text, x, y, scaleX, scaleY, ...)
            return sourceFont:DrawStringScaledUTF8(text, x, y, scaleX * 0.5, scaleY * 0.5, ...)
        end
        EID.font = scaledFont
        EID.ArabicPreviewDensityFont = true
    end
    EID.descriptions.en_us = deepCopy(EID.descriptions.en_us)
    -- EID 5.03 (standard Repentance) does not initialize ItemNames.
    EID.ItemNames = EID.ItemNames or {}
    EID.ItemNames.en_us = deepCopy(EID.ItemNames.en_us or {})
    local function supportsLayer(layer)
        if layer == "rep+" then return false end
        if layer == "rep" then return EID.isRepentance == true or EID.isRepentancePlus == true end
        return layer == "ab+"
    end
    -- Keep EID's English transformation identifiers intact: getTransformationIcon
    -- resolves sprite names from this table. Translate only the visible label.
    local originalGetTransformationName = EID.getTransformationName
    if originalGetTransformationName then
        function EID:getTransformationName(id)
            local numericID = tonumber(id)
            local translatedName = numericID and translations.transformations[numericID + 1]
            if translatedName then return translatedName end
            return originalGetTransformationName(self, id)
        end
    end
    for _, row in ipairs(translations.auxiliary) do
      if supportsLayer(row.layer) then
        local target = EID.descriptions.en_us
        if row.path == "" then
            target[row.category] = row.text
        else
            target = target[row.category]
            local parts = {}
            for part in string.gmatch(row.path, "[^/]+") do table.insert(parts, part) end
            for index, part in ipairs(parts) do
                local kind, value = string.match(part, "^([sn]):(.*)$")
                local key = kind == "n" and tonumber(value) or value
                if type(target) ~= "table" then target = nil; break end
                if index < #parts then
                    target = target[key]
                else
                    target[key] = row.text
                end
            end
        end
      end
    end
    local counts = {collectibles=0, trinkets=0, cards=0, pills=0, horsepills=0, sacrifice=0, dice=0}
    for _, row in ipairs(translations.collectibles) do if supportsLayer(row.layer) then EID:addCollectible(row.id, row.desc, row.name, "en_us"); counts.collectibles = counts.collectibles + 1 end end
    for _, row in ipairs(translations.trinkets) do if supportsLayer(row.layer) then EID:addTrinket(row.id, row.desc, row.name, "en_us"); counts.trinkets = counts.trinkets + 1 end end
    for _, row in ipairs(translations.cards) do if supportsLayer(row.layer) then EID:addCard(row.id, row.desc, row.name, "en_us"); counts.cards = counts.cards + 1 end end
    for _, row in ipairs(translations.pills) do if supportsLayer(row.layer) then EID:addPill(row.id, row.desc, row.name, "en_us"); counts.pills = counts.pills + 1 end end
    for _, row in ipairs(translations.horsepills) do if supportsLayer(row.layer) then EID:addHorsePill(row.id, row.desc, row.name, "en_us"); counts.horsepills = counts.horsepills + 1 end end
    for _, row in ipairs(translations.sacrifice) do if supportsLayer(row.layer) then EID.descriptions.en_us.sacrifice[row.id] = {tostring(row.id), "", row.desc}; counts.sacrifice = counts.sacrifice + 1 end end
    for _, row in ipairs(translations.dice) do if supportsLayer(row.layer) then EID.descriptions.en_us.dice[row.id] = {tostring(row.id), "", row.desc}; counts.dice = counts.dice + 1 end end
    Isaac.DebugString(string.format("Arabic EID: loaded %d drafts (collectibles %d, trinkets %d, cards %d, pills %d, horse pills %d, sacrifice %d, dice %d); font=%s via %s; 2x-density font compensated at runtime; Arabic temporarily replaces English (no saved language change).",
        counts.collectibles + counts.trinkets + counts.cards + counts.pills + counts.horsepills + counts.sacrifice + counts.dice,
        counts.collectibles, counts.trinkets, counts.cards, counts.pills, counts.horsepills, counts.sacrifice, counts.dice, tostring(fontOK), fontPath))
end
mod:AddCallback(ModCallbacks.MC_POST_GAME_STARTED, installArabic)
